if (after.source === 0 && after.target === 0) {
  console.log('PASS: hint auto-hid after 10s');
} else {
  console.log('FAIL: hint still visible after 10s - bug reproduced');
  // dump more info
  const dump = await page.evaluate(() => {
    return {
      hintSourceEls: [...document.querySelectorAll('#game .card')].filter(e=>e.classList.contains('hint-source')).map(e=>e.dataset.cardId),
